const chunks = $input.all().map(i => i.json);
const norm = $('Güncellemeyi Normalle').first().json;
const ingest = $('PREI: Ingest').first().json;
const hist = $('Gecmis Metni Derle').first().json;
const knowledgeText = chunks.length ? chunks.map((k, i) => '[' + (i + 1) + '] ' + (k.content || '').slice(0, 900)).join('\n\n') : '(İlgili bilgi bankası içeriği bulunamadı, bu konuda dürüst ol, uydurma.)';
const raw = norm.text || '';
const tr = /[çğışöüÇĞİŞÖÜ]/.test(raw) || /\b(ve|bir|için|nasıl|merhaba|selam|istiyorum|yatırım|nedir|mısın|miyim|evet|hayır|teşekkür)\b/i.test(raw);
const en = /\b(the|and|for|hello|invest|property|want|can you|help|how|what|residence|buy|looking|thanks|please)\b/i.test(raw);
const replyLang = tr ? 'Türkçe' : (en ? 'English' : 'Türkçe');
return [{ json: { text: norm.text, chatId: norm.chatId, leadId: ingest.lead_id, knowledgeText, historyText: hist.historyText, replyLang } }];

