parameters.jsCode:
const ctx = $('Extraction Prompt').first().json;
let extracted = {};
let hasData = false;
try {
  extracted = JSON.parse($input.first().json.choices[0].message.content);
  hasData = Object.keys(extracted).some(k => k === 'criteria'
    ? (extracted.criteria && Object.keys(extracted.criteria).length > 0)
    : (extracted[k] !== undefined && extracted[k] !== null && extracted[k] !== ''));
} catch (e) {
  hasData = false;
}
return [{ json: { leadId: ctx.leadId, extracted, hasData } }];

const msgs = $input.all().map(i => i.json).filter(m => m && (m.body !== undefined || m.direction));
const norm = $('Güncellemeyi Normalle').first().json;
const ingest = $('PREI: Ingest').first().json;
const recent = msgs.slice(0, 10).reverse();
const historyText = recent.length ? recent.map(m => (m.direction === 'inbound' ? 'MÜŞTERİ' : 'EYLÜL') + ': ' + (m.body || '').slice(0, 500)).join('\n') : '(Önceki mesaj yok, bu ilk konuşma.)';
let greeting = 'Merhaba';
try { const h = $now.setZone('Europe/Istanbul').hour; greeting = h < 6 ? 'İyi akşamlar' : (h < 12 ? 'Günaydın' : (h < 18 ? 'İyi günler' : 'İyi akşamlar')); } catch (e) {}
const tt = (norm.text || '').toLowerCase().trim().replace(/[!?.,\s]+$/g, '');
const isGreeting = /^(selam|selamlar|merhaba|mrb|slm|sa|gunaydin|günaydın|iyi akşamlar|iyi aksamlar|iyi günler|iyi gunler|iyi geceler|nasılsın|nasilsin|nasılsınız|naber|nbr|ne haber|hey|hi|hello|alo)$/.test(tt);
const hasHistory = recent.length > 0;
return [{ json: { text: norm.text, chatId: norm.chatId, leadId: ingest.lead_id, historyText, greeting, isGreeting, hasHistory } }];

// Eylül'ün cevabını gönderilmeden ÖNCE süzer. Yasakları prompt'a yazmak
// iki kez denendi ve tutmadı (ölçüldü: sıcaklık 0.3 ve yasak listesi
// üretimden hemen öncedeyken gpt-4o yine "harika" yazdı). Son savunma burası.
const out = $('Eylül AI Agent').first().json.output || '';
const hist = ($('Gecmis Metni Derle').first().json.historyText || '').trim();
let t = out;
const dokunulan = [];

// 1) Dolgu kapanışları. Kalıp genişletildi: canlıda "yardımcı olabilirsem
//    lütfen belirtin" ve "sorunuz olursa buradayım" biçimleri kaçmıştı.
const dolgu = /\s*(Başka (?:bir konuda|sorunuz)[^.?!]*[.?!]|Yardımcı olmaktan (?:mutluluk|memnuniyet) duyarım\.?|Size nasıl yardımcı olabilirim\?|Herhangi bir sorunuz olursa buradayım\.?)\s*$/gi;
if (dolgu.test(t)) { t = t.replace(dolgu, ''); dokunulan.push('dolgu-kapanis'); }

// 2) Coşku sıfatları. Nitelediği ismi bozmamak için "X bir" kalıbı nötrlenir.
const esle = [
  [/\bharika bir\b/gi, 'iyi bir'],
  [/\bmükemmel bir\b/gi, 'güçlü bir'],
  [/\bsüper bir\b/gi, 'iyi bir'],
  [/\bçok güzel bir\b/gi, 'iyi bir'],
  [/,?\s*(ne kadar )?heyecan verici\b/gi, ''],
  [/,?\s*heyecanlandım\b/gi, ''],
  [/\b(Harika|Mükemmel|Süper)[!.]\s*/g, ''],
  [/\bkesinlikle!/gi, 'evet.'],
];
for (const [re, ile] of esle) { if (re.test(t)) { t = t.replace(re, ile); dokunulan.push('cosku'); } }

// 3) Ünlem ve emoji.
if (t.includes('!')) { t = t.replace(/!+/g, '.'); dokunulan.push('unlem'); }
const emoji = /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{1F900}-\u{1F9FF}]/gu;
if (emoji.test(t)) { t = t.replace(emoji, ''); dokunulan.push('emoji'); }

// 4) İlk mesaj DEĞİLSE baştaki selamı at. Üç kalıp: selam-önce
//    ("Merhaba Ahmet Bey,"), isim-önce ("Ahmet Bey, merhaba.") ve
//    "Tekrar merhaba." — sonuncusu tek parça atılır, yoksa geriye
//    "Tekrar." diye anlamsız bir artık kalıyordu (canlıda görüldü).
if (hist) {
  const selam = new RegExp("^\\s*(?:(?:Tekrar|Yeniden)\\s+)?(?:(?:Merhaba(?:lar)?|Selam(?:lar)?|Hoş geldiniz)(?:\\s+[A-ZÇĞİÖŞÜ][a-zçğıöşü]+(?:\\s+(?:Bey|Hanım))?)?|[A-ZÇĞİÖŞÜ][a-zçğıöşü]+(?:\\s+(?:Bey|Hanım))?\\s*,?\\s*(?:Merhaba(?:lar)?|Selam(?:lar)?|Hoş geldiniz))\\s*[,.!]?\\s*", "i");
  if (selam.test(t)) { t = t.replace(selam, ''); dokunulan.push('tekrar-selam'); }
}

// 5) Artıkları topla.
t = t.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n')
     .replace(/^[\s,.;:]+/, '').replace(/\s+([,.;:])/g, '$1').trim();

// Türkçe duyarlı büyütme: toUpperCase() "i" harfini "I" yapar, doğrusu "İ".
if (t && /^[a-zçğıöşü]/.test(t)) { t = t.charAt(0).toLocaleUpperCase('tr') + t.slice(1); }

// SON SAVUNMA: süzgeç metni tamamen boşalttıysa orijinali döndür.
// Kusurlu bir cevap, boş cevaptan her zaman iyidir.
if (!t.trim()) { t = out.trim(); dokunulan.push('bos-kaldi-geri-alindi'); }

if (dokunulan.length) { console.log('Üslup süzgeci: ' + [...new Set(dokunulan)].join(', ')); }
return [{ json: { text: t, suzuldu: [...new Set(dokunulan)] } }];
